(function(){'use strict';
const $=id=>document.getElementById(id),api=()=>window.CAGE_BACKEND,esc=escapeHtml,me=()=>api()?.currentProfile()?.id;
let receipts=[],receiptThread='',receiptReady=false,receiptError='',busy=false,interval,readTimer,prefs={banners:true,sound:true,desktop:false,chat:true,mentions:true,tasks:true,reminders:true,approvals:true,other:true,muted_threads:[]},audio,lastBeep=0,baseline=false,seen=new Set(),acked=new Set();
const chat=$('chat-messages'),input=$('chat-input'),workspace=document.querySelector('.chat-workspace');
const settingsKey=()=>`cage-notifications-seen:${me()}`,draftKey=t=>`cage-chat-draft:${me()}:${t}`;
function modal(title,content){let d=$('hub-detail-dialog');if(!d){d=document.createElement('dialog');d.id='hub-detail-dialog';d.className='app-dialog academy-dialog';document.body.append(d);}d.innerHTML=`<div class="dialog-heading"><h2>${esc(title)}</h2><button type="button" class="icon-button" data-hub-close aria-label="Close">×</button></div>${content}<p id="hub-detail-error" class="form-error" role="alert"></p>`;if(!d.open)d.showModal();return d;}
function autoSize(){input.style.height='auto';input.style.height=Math.min(input.scrollHeight,matchMedia('(max-width:680px)').matches?110:150)+'px';}
function saveDraft(thread=activeChatThread){if(!me()||!thread)return;try{sessionStorage.setItem(draftKey(thread),input.value);}catch{}}
function switchDraft(previous,next){if(previous===next)return;saveDraft(previous);try{input.value=sessionStorage.getItem(draftKey(next))||'';}catch{input.value='';}autoSize();}
function layout(){document.body.classList.toggle('chat-mode',activeView==='chat');const sync=document.querySelector('.ops-sync');if(sync&&!sync.dataset.relocated){document.querySelector('.topbar-actions').prepend(sync);sync.dataset.relocated='true';}autoSize();}
const oldSet=setView;setView=function(view,...args){const previous=activeView;const result=oldSet(view,...args);layout();if(view==='chat'&&previous!=='chat'){try{input.value=sessionStorage.getItem(draftKey(activeChatThread))||input.value;}catch{}refreshReceipts();}if(view!==previous)document.querySelector('.main-content')?.scrollTo?.({top:0});return result;};
input.addEventListener('input',()=>{autoSize();saveDraft();});window.addEventListener('pagehide',()=>saveDraft());
function receiptLabel(id){
 if(api()?.reviewSync?.().some(p=>p.key==='messages'&&p.id===id&&p.before==null))return 'Sending…';
 if(!receiptReady||receiptThread!==activeChatThread)return 'Checking…';if(receiptError)return 'Receipt unavailable';
 const r=receipts.filter(r=>r.message_id===id);if(!r.length)return 'Sent · no receipt data';
 const read=r.filter(r=>r.read_at).length,delivered=r.filter(r=>r.delivered_at).length;
 if(r.length===1)return read?'✓✓ Read':delivered?'✓✓ Delivered':'✓ Sent';
 return read===r.length?`✓✓ Read by all (${read})`:read?`Read ${read}/${r.length} · Delivered ${delivered}/${r.length}`:delivered?`Delivered ${delivered}/${r.length}`:`Sent to ${r.length}`;
}
function labels(){document.querySelectorAll('[data-receipt]').forEach(b=>{b.textContent=receiptLabel(b.dataset.receipt);b.classList.toggle('is-read',receipts.some(r=>r.message_id===b.dataset.receipt&&r.read_at));});}
function visibleKeys(){
 if(document.hidden||!document.hasFocus()||activeView!=='chat'||!chat.getClientRects().length||document.querySelector('dialog[open]'))return [];
 const bounds=chat.getBoundingClientRect();return [...chat.querySelectorAll('[data-message-id]:not(.mine)')].filter(el=>{const r=el.getBoundingClientRect();return Math.min(r.bottom,bounds.bottom)-Math.max(r.top,bounds.top)>=Math.min(r.height,bounds.height)*.5&&r.width>0;}).map(el=>el.dataset.messageId);
}
function scheduleRead(){clearTimeout(readTimer);readTimer=setTimeout(async()=>{const ids=visibleKeys().filter(id=>!acked.has(id));if(!ids.length)return;try{await api().acknowledgeChat(ids,true);ids.forEach(id=>acked.add(id));await window.CAGE_PERSONAL?.refresh?.();await refreshReceipts();}catch{receiptError='Read status is waiting for connection';}},650);}
async function acknowledgeDelivered(){if(!me()||!api()?.acknowledgeChat)return;const ids=state.messages.slice(-500).map(m=>m.id);if(ids.length)await api().acknowledgeChat(ids,false);}
async function refreshReceipts(){if(!me()||!activeChatThread||busy||api().moduleLevel('chat')==='none')return;busy=true;const thread=activeChatThread;try{await acknowledgeDelivered();const rows=await api().chatReceipts(thread);if(activeChatThread===thread){receipts=rows;receiptThread=thread;receiptReady=true;receiptError='';rows.filter(r=>r.recipient_id===me()&&r.read_at).forEach(r=>acked.add(r.message_id));labels();scheduleRead();}}catch(e){receiptError=e.message;receiptReady=true;labels();}finally{busy=false;}}
const jump=document.createElement('button');jump.className='chat-jump';jump.type='button';jump.textContent='↓ Latest messages';jump.hidden=true;document.querySelector('.chat-main').append(jump);jump.onclick=()=>{chat.scrollTop=chat.scrollHeight;scheduleRead();};
chat.addEventListener('scroll',()=>{jump.hidden=chat.scrollHeight-chat.scrollTop-chat.clientHeight<120;scheduleRead();},{passive:true});
function rendered(){layout();labels();autoSize();jump.hidden=chat.scrollHeight-chat.scrollTop-chat.clientHeight<120;scheduleRead();const head=$('chat-header');if(!head.querySelector('[data-chat-info]'))head.querySelector('.chat-header-actions')?.insertAdjacentHTML('afterbegin','<button type="button" data-chat-info>Details</button><button type="button" data-chat-mute>Mute</button>');const mute=head.querySelector('[data-chat-mute]');if(mute)mute.textContent=prefs.muted_threads.includes(activeChatThread)?'Unmute':'Mute';if(receiptThread!==activeChatThread){receiptReady=false;refreshReceipts();}}
function receiptDetails(id){const rows=receipts.filter(r=>r.message_id===id),format=d=>new Date(d).toLocaleString();modal('Message delivery & reads',rows.length?`<p>Delivered means received by a recipient’s Hub. Read means visible in their active conversation.</p><ul class="receipt-list">${rows.map(r=>`<li><strong>${esc(r.recipient_name)}</strong><span>${r.read_at?'Read':r.delivered_at?'Delivered':'Sent · not delivered yet'}${r.delivered_at?`<small>Delivered ${esc(format(r.delivered_at))}</small>`:''}${r.read_at?`<small>Read ${esc(format(r.read_at))}</small>`:''}</span></li>`).join('')}</ul>`:'<p>No delivery history is available. Tracking starts with messages sent after this update; no historical read times are invented.</p>');}
async function unlockSound(){if(!prefs.sound)return;try{const Audio=window.AudioContext||window.webkitAudioContext;if(!Audio)return;audio ||= new Audio();if(audio.state==='suspended')await audio.resume();}catch{}}
async function beep(test=false){if(!prefs.sound&&!test)return;if(!test&&Date.now()-lastBeep<2500)return;await unlockSound();if(!audio||audio.state!=='running')return;lastBeep=Date.now();const oscillator=audio.createOscillator(),gain=audio.createGain();oscillator.connect(gain);gain.connect(audio.destination);oscillator.frequency.value=780;gain.gain.setValueAtTime(.0001,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.08,audio.currentTime+.02);gain.gain.exponentialRampToValueAtTime(.0001,audio.currentTime+.18);oscillator.start();oscillator.stop(audio.currentTime+.2);}
document.addEventListener('pointerdown',unlockSound,{passive:true});
const alerts=document.createElement('div');alerts.className='hub-alert-stack';alerts.setAttribute('aria-live','polite');document.body.append(alerts);
function navigateNotice(n){api().readNotification(n.id).then(()=>window.CAGE_PERSONAL?.refresh?.()).catch(()=>{});setView(n.target_view);if(['notices','calendar'].includes(n.target_view))window.CAGE_COLLAB?.open(n.target_view,n.target_id).catch(e=>showToast(e.message));else if(n.target_view==='chat')selectChatThread(n.target_id);else if(n.target_view==='projects')openProject(n.target_id);else if(n.target_view==='tasks')openTask(n.target_id);else if(n.target_view==='requests')openRequest(n.target_id);}
function alertNotice(n){const div=document.createElement('div');div.className='hub-alert';div.innerHTML=`<button type="button"><strong>${esc(n.title)}</strong><span>${esc(n.body||'Open to view')}</span></button><button type="button" aria-label="Dismiss notification">×</button>`;div.children[0].onclick=()=>{navigateNotice(n);div.remove();};div.children[1].onclick=()=>div.remove();alerts.append(div);while(alerts.children.length>3)alerts.firstChild.remove();setTimeout(()=>div.remove(),10000);}
function category(n){if(n.event_key?.startsWith('mention:'))return 'mentions';if(n.target_view==='chat')return 'chat';if(n.target_view==='tasks')return 'tasks';if(n.target_view==='mywork')return 'reminders';if(n.target_view==='approvals')return 'approvals';return 'other';}
function receiveNotifications(list){if(!me())return;
 if(!baseline){try{const old=JSON.parse(localStorage.getItem(settingsKey())||'null');if(old)seen=new Set(old);else list.forEach(n=>seen.add(n.id));}catch{list.forEach(n=>seen.add(n.id));}baseline=true;}
 // Merge another tab's already-announced ids before claiming this batch.
 try{JSON.parse(localStorage.getItem(settingsKey())||'[]').forEach(id=>seen.add(id));}catch{}
 const fresh=list.filter(n=>!seen.has(n.id));list.forEach(n=>seen.add(n.id));try{localStorage.setItem(settingsKey(),JSON.stringify([...seen].slice(-1000)));}catch{}
 for(const n of fresh){if(n.read_at||!prefs[category(n)]||(n.target_view==='chat'&&prefs.muted_threads.includes(n.target_id)))continue;
 const msg=n.event_key?.replace(/^(mention|chat):/,'').replace(/:[^:]+$/,'');if(n.target_view==='chat'&&n.target_id===activeChatThread&&visibleKeys().includes(msg))continue;
 if(prefs.banners)alertNotice(n);beep();if(prefs.desktop&&document.hidden&&window.Notification?.permission==='granted'){const alert=new Notification('CAGE · '+n.title,{body:'Open CAGE to view the update.',tag:n.id});alert.onclick=()=>{window.focus();navigateNotice(n);alert.close();};}
 }
}
function preferences(){const names={banners:'Show in-app notification banners',sound:'Play a short notification sound',desktop:'Desktop alerts while the Hub tab is open',chat:'Chat messages',mentions:'Mentions and @all',tasks:'Task assignments',reminders:'Personal reminders',approvals:'Approvals',other:'Other work updates'};modal('Notification preferences',`<form id="hub-notifications-form" data-personal-readonly><div class="notification-toggles">${Object.entries(names).map(([k,v])=>`<label><input name="${k}" type="checkbox" ${prefs[k]?'checked':''}>${v}</label>`).join('')}</div><p class="academy-muted">These settings control alerts; records remain in your notification centre. Muted conversations: ${prefs.muted_threads.length}. Email preferences are managed separately. Sound starts after you interact with the page.</p><div class="dialog-actions"><button type="button" data-sound-test class="secondary-button">Test sound</button><button class="primary-button">Save preferences</button></div></form>`);}
const prefButton=document.createElement('button');prefButton.className='secondary-button';prefButton.textContent='App notifications';prefButton.onclick=preferences;document.querySelector('[data-view-panel="notifications"] .section-intro').append(prefButton);
document.addEventListener('submit',async e=>{if(e.target.id!=='hub-notifications-form')return;e.preventDefault();const f=e.target,b=e.submitter;b.disabled=true;try{const next={...prefs};delete next.user_id;delete next.updated_at;for(const el of f.querySelectorAll('input[type="checkbox"]'))next[el.name]=el.checked;if(next.desktop){if(!window.Notification)throw new Error('Desktop alerts are not supported in this browser. In-app alerts and sound remain available.');const permission=await Notification.requestPermission();if(permission!=='granted'){next.desktop=false;f.elements.desktop.checked=false;}}await api().appNotificationPreferences(next);prefs=next;$('hub-detail-dialog').close();}catch(err){$('hub-detail-error').textContent=err.message;}finally{b.disabled=false;}});
function financialRecord(type,id){const record=(type==='quote'?state.quotes:type==='invoice'?state.invoices:state.expenses).find(r=>r.id===id);if(!record){showToast('This record is unavailable under your current access.');return;}const fields=type==='expense'?{Project:projectById(record.project)?.name,Category:record.category,Date:record.date,Status:record.status||'Recorded',Receipt:record.receipt||'Not specified'}:{Client:record.client,Project:projectById(record.project||dealById(record.deal)?.project)?.name,Recipient:record.recipient,Issued:record.issued,[type==='quote'?'Valid until':'Due']:record.validUntil||record.due,Status:record.status};modal(record.number||'Expense record',`<h3>${esc(record.description)}</h3><p><strong>${esc(record.currency||'MWK')} ${Number(record.amount).toLocaleString()}</strong></p><dl class="record-summary">${Object.entries(fields).map(([k,v])=>`<div><dt>${k}</dt><dd>${esc(v||'—')}</dd></div>`).join('')}</dl>${record.items?.length?`<div class="academy-table"><table><thead><tr><th>Item</th><th>Qty</th><th>Unit price</th></tr></thead><tbody>${record.items.map(i=>`<tr><td>${esc(i.description)}</td><td>${Number(i.quantity)}</td><td>${Number(i.unitPrice).toLocaleString()}</td></tr>`).join('')}</tbody></table></div>`:''}<p class="record-details">${esc(record.serviceDetails||record.notes||'')}</p><div class="dialog-actions">${type!=='expense'?`<button class="secondary-button" data-record-pdf="${type}" data-id="${id}">View / download PDF</button>${api().moduleLevel('finance')==='edit'?`<button class="primary-button" data-send-document="${type}" data-document-id="${id}">${record.sentAt?'Resend':'Send'}</button>`:''}`:record.receiptPath?`<button class="secondary-button" data-open-receipt="${id}">Open receipt</button>`:'<span>No receipt attached</span>'}</div>`);}
const finance=document.querySelector('[data-view-panel="finance"]');finance.dataset.financeTab=matchMedia('(max-width:680px)').matches?'invoices':'overview';const tabs=document.createElement('nav');tabs.className='finance-view-tabs';tabs.setAttribute('aria-label','Finance sections');tabs.innerHTML=['overview','quotes','invoices','expenses'].map(k=>`<button data-finance-section="${k}" class="${finance.dataset.financeTab===k?'active':''}">${k[0].toUpperCase()+k.slice(1)}</button>`).join('');finance.querySelector('.page-intro').after(tabs);
let expenseLimit=20;
const expenseControls=document.createElement('div');expenseControls.className='academy-filter';expenseControls.innerHTML='<input type="search" id="expense-record-search" aria-label="Search expenses" placeholder="Find an expense, project or category"><span id="expense-page-count" class="academy-muted"></span><button type="button" class="secondary-button" id="expense-load-more">Show more</button>';
$('expense-list').before(expenseControls);
function filterExpenses(){const query=$('expense-record-search').value.toLowerCase();let count=0,total=0;for(const row of $('expense-list').children){const match=row.textContent.toLowerCase().includes(query);if(match)total++;const visible=match&&count++<expenseLimit;row.hidden=!visible;row.style.setProperty('display',visible?'':'none','important');}$('expense-page-count').textContent=Math.min(total,expenseLimit)+' of '+total;$('expense-load-more').hidden=total<=expenseLimit;}
$('expense-record-search').addEventListener('input',()=>{expenseLimit=20;filterExpenses();});$('expense-load-more').onclick=()=>{expenseLimit+=20;filterExpenses();};
new MutationObserver(filterExpenses).observe($('expense-list'),{childList:true});filterExpenses();
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;try{
 if(b.hasAttribute('data-hub-close'))$('hub-detail-dialog').close();
 if(b.dataset.receipt)receiptDetails(b.dataset.receipt);
 if(b.hasAttribute('data-chat-info'))$('chat-context').classList.toggle('expanded');
 if(b.hasAttribute('data-chat-mute')){const set=new Set(prefs.muted_threads);if(set.has(activeChatThread))set.delete(activeChatThread);else set.add(activeChatThread);const updated={...prefs,muted_threads:[...set]};delete updated.user_id;delete updated.updated_at;await api().appNotificationPreferences(updated);prefs=updated;rendered();}
 if(b.hasAttribute('data-sound-test')){const previous=prefs.sound;prefs.sound=true;unlockSound();beep(true);prefs.sound=previous;}
 if(b.dataset.newQuoteProject){const id=b.dataset.newQuoteProject,deal=state.deals.find(d=>d.project===id);openQuoteDialog(deal?.id||'',id);}
 if(b.dataset.viewDocument)financialRecord(b.dataset.viewDocument,b.dataset.recordId);
 if(b.dataset.recordPdf){const r=(b.dataset.recordPdf==='quote'?state.quotes:state.invoices).find(r=>r.id===b.dataset.id);await window.CAGE_DOCUMENTS.preview(r,b.dataset.recordPdf);}
 if(b.dataset.financeSection){finance.dataset.financeTab=b.dataset.financeSection;tabs.querySelectorAll('button').forEach(el=>el.classList.toggle('active',el===b));try{sessionStorage.setItem('cage-finance-tab:'+me(),b.dataset.financeSection);}catch{}}
 }catch(err){if($('hub-detail-dialog')?.open)$('hub-detail-error').textContent=err.message;else showToast(err.message);}});
window.addEventListener('cage:personal-notifications',e=>receiveNotifications(e.detail));
window.addEventListener('cage:messages-loaded',refreshReceipts);window.addEventListener('cage:sync',refreshReceipts);
window.addEventListener('focus',()=>{refreshReceipts();scheduleRead();});document.addEventListener('visibilitychange',()=>{if(!document.hidden){refreshReceipts();scheduleRead();}});
window.addEventListener('cage:session-ready',async()=>{baseline=false;seen=new Set();acked.clear();receiptReady=false;prefs={banners:true,sound:true,desktop:false,chat:true,mentions:true,tasks:true,reminders:true,approvals:true,other:true,muted_threads:[]};try{prefs={...prefs,...await api().appNotificationPreferences()};const selected=sessionStorage.getItem('cage-finance-tab:'+me());if(selected){finance.dataset.financeTab=selected;tabs.querySelectorAll('button').forEach(b=>b.classList.toggle('active',b.dataset.financeSection===selected));}}catch(e){showToast('Notification preferences could not load. Check migration 015.');}layout();refreshReceipts();clearInterval(interval);interval=setInterval(()=>{if(!document.hidden){refreshReceipts();window.CAGE_PERSONAL?.refresh?.();}},6000);});
window.CAGE_CHAT={receiptLabel,rendered,switchDraft,sent(thread){try{sessionStorage.removeItem(draftKey(thread));}catch{}input.style.height='44px';chat.scrollTop=chat.scrollHeight;setTimeout(()=>chat.scrollTop=chat.scrollHeight,0);},visibleKeys,refresh:refreshReceipts};
window.CAGE_RECORDS={open:financialRecord};layout();
})();
